import pytest
from mdinline import render


class TestBasicEmphasis:
    """Test basic emphasis (single *) and strong emphasis (double **)."""

    def test_single_star_emphasis(self):
        assert render("*hello*") == "<em>hello</em>"

    def test_double_star_strong_emphasis(self):
        assert render("**hello**") == "<strong>hello</strong>"

    def test_triple_star_strong_and_emphasis(self):
        assert render("***hello***") == "<em><strong>hello</strong></em>"

    def test_emphasis_with_text_around(self):
        assert render("*Hello* **world**") == "<em>Hello</em> <strong>world</strong>"

    def test_multiple_emphasis_runs(self):
        assert render("*a* *b* *c*") == "<em>a</em> <em>b</em> <em>c</em>"

    def test_multiple_strong_runs(self):
        assert render("**a** **b**") == "<strong>a</strong> <strong>b</strong>"

    def test_nested_emphasis(self):
        assert render("**bold *and* italic**") == "<strong>bold <em>and</em> italic</strong>"

    def test_nested_strong_in_emphasis(self):
        assert render("*italic **bold** italic*") == "<em>italic <strong>bold</strong> italic</em>"


class TestUnderscoreEmphasis:
    """Test emphasis with underscore (_) character."""

    def test_single_underscore_emphasis(self):
        assert render("_hello_") == "<em>hello</em>"

    def test_double_underscore_strong_emphasis(self):
        assert render("__hello__") == "<strong>hello</strong>"

    def test_triple_underscore_strong_and_emphasis(self):
        assert render("___hello___") == "<em><strong>hello</strong></em>"

    def test_underscore_in_word_no_emphasis(self):
        assert render("snake_case_name") == "snake_case_name"

    def test_underscore_with_space_before_is_emphasis(self):
        assert render("hello _world_") == "hello <em>world</em>"

    def test_underscore_with_space_after_is_emphasis(self):
        assert render("_hello_ world") == "<em>hello</em> world"

    def test_underscore_at_word_boundary_start_no_emphasis(self):
        assert render("_snake_case") == "_snake_case"

    def test_underscore_at_word_boundary_end_no_emphasis(self):
        assert render("snake_case_") == "snake_case_"

    def test_underscore_with_punctuation_before_can_open(self):
        assert render("._hello_") == ".<em>hello</em>"

    def test_underscore_with_punctuation_after_can_close(self):
        assert render("_hello_.") == "<em>hello</em>."


class TestCodeSpans:
    """Test code span rendering with backticks."""

    def test_single_backtick_code_span(self):
        assert render("`code`") == "<code>code</code>"

    def test_code_span_with_asterisk(self):
        assert render("use `a*b` here") == "use <code>a*b</code> here"

    def test_code_span_with_leading_trailing_space(self):
        assert render("` a `") == "<code>a</code>"

    def test_code_span_with_only_spaces(self):
        assert render("`  `") == "<code>  </code>"

    def test_code_span_with_leading_space_only(self):
        assert render("` a`") == "<code> a</code>"

    def test_code_span_with_trailing_space_only(self):
        assert render("`a `") == "<code>a </code>"

    def test_double_backtick_code_span(self):
        assert render("``a ` b``") == "<code>a ` b</code>"

    def test_triple_backtick_code_span(self):
        assert render("```a `` b```") == "<code>a `` b</code>"

    def test_code_span_unmatched_backtick_is_plain_text(self):
        assert render("` unmatched") == "` unmatched"

    def test_code_span_with_different_length_backticks_no_match(self):
        assert render("`a``b`") == "`a``b`"

    def test_code_span_binds_tighter_than_emphasis(self):
        assert render("*a `*` b*") == "<em>a <code>*</code> b</em>"

    def test_code_span_with_underscore_no_emphasis(self):
        assert render("`_`") == "<code>_</code>"

    def test_code_span_contains_backslash_literally(self):
        assert render("`\\*`") == "<code>\\*</code>"

    def test_multiple_code_spans(self):
        assert render("`a` and `b`") == "<code>a</code> and <code>b</code>"


class TestBackslashEscapes:
    """Test backslash escape sequences."""

    def test_escape_asterisk(self):
        assert render("\\*not emphasis\\*") == "*not emphasis*"

    def test_escape_underscore(self):
        assert render("\\_not emphasis\\_") == "_not emphasis_"

    def test_escape_backtick(self):
        assert render("\\`not code\\`") == "`not code`"

    def test_escape_other_punctuation(self):
        assert render("\\[\\]\\(\\)") == "[]()\"" if "\\\"" == "\"" else "[]()\\\"" 

    def test_escape_bracket(self):
        assert render("\\[link\\]") == "[link]"

    def test_escape_paren(self):
        assert render("\\(text\\)") == "(text)"

    def test_escape_exclamation(self):
        assert render("\\!") == "!"

    def test_escape_before_non_punctuation_is_literal(self):
        assert render("\\a") == "\\a"

    def test_escape_at_end_of_line_is_literal(self):
        assert render("text\\") == "text\\"

    def test_escaped_backtick_not_a_backtick_string(self):
        assert render("\\`a`") == "`a`"

    def test_escape_in_code_span_is_literal(self):
        assert render("`\\*`") == "<code>\\*</code>"

    def test_multiple_escapes(self):
        assert render("\\*\\*\\*") == "***"


class TestHTMLEscaping:
    """Test HTML entity escaping."""

    def test_escape_ampersand(self):
        assert render("a & b") == "a &amp; b"

    def test_escape_less_than(self):
        assert render("a < b") == "a &lt; b"

    def test_escape_greater_than(self):
        assert render("a > b") == "a &gt; b"

    def test_escape_quote(self):
        assert render('a " b') == "a &quot; b"

    def test_multiple_special_characters(self):
        assert render("a < b & c") == "a &lt; b &amp; c"

    def test_escape_in_code_span(self):
        assert render("`<>&\"`") == "<code>&lt;&gt;&amp;&quot;</code>"

    def test_escape_in_emphasis(self):
        assert render("*a < b*") == "<em>a &lt; b</em>"

    def test_escape_ampersand_as_entity_is_literal(self):
        assert render("&amp;") == "&amp;amp;"

    def test_escape_all_special_chars_together(self):
        assert render("&<>\"") == "&amp;&lt;&gt;&quot;"


class TestInputValidation:
    """Test input validation."""

    def test_newline_raises_value_error(self):
        with pytest.raises(ValueError):
            render("one\ntwo")

    def test_carriage_return_raises_value_error(self):
        with pytest.raises(ValueError):
            render("one\rtwo")

    def test_crlf_raises_value_error(self):
        with pytest.raises(ValueError):
            render("one\r\ntwo")

    def test_newline_at_start_raises_value_error(self):
        with pytest.raises(ValueError):
            render("\ntext")

    def test_newline_at_end_raises_value_error(self):
        with pytest.raises(ValueError):
            render("text\n")

    def test_empty_string_is_valid(self):
        assert render("") == ""

    def test_whitespace_only_is_valid(self):
        assert render("   ") == "   "


class TestWhitespaceHandling:
    """Test whitespace preservation."""

    def test_leading_whitespace_preserved(self):
        assert render("  text") == "  text"

    def test_trailing_whitespace_preserved(self):
        assert render("text  ") == "text  "

    def test_internal_whitespace_preserved(self):
        assert render("a   b") == "a   b"

    def test_tab_preserved(self):
        assert render("a\tb") == "a\tb"

    def test_space_between_emphasis_and_text(self):
        assert render("*hello* world") == "<em>hello</em> world"


class TestEdgeCasesAndRegressions:
    """Test edge cases and corner scenarios."""

    def test_empty_code_span(self):
        assert render("``") == "``"

    def test_empty_emphasis_star(self):
        assert render("**") == "**"

    def test_empty_emphasis_underscore(self):
        assert render("__") == "__"

    def test_unmatched_emphasis_star(self):
        assert render("*unmatched") == "*unmatched"

    def test_unmatched_strong_emphasis_star(self):
        assert render("**unmatched") == "**unmatched"

    def test_mismatched_delimiter_chars(self):
        assert render("*hello_") == "*hello_"

    def test_emphasis_with_internal_whitespace(self):
        assert render("*hello world*") == "<em>hello world</em>"

    def test_strong_with_internal_whitespace(self):
        assert render("**hello world**") == "<strong>hello world</strong>"

    def test_four_stars_two_on_each_side(self):
        assert render("****") == "****"

    def test_unmatched_backticks_longer_than_later_backticks(self):
        assert render("```a`b`") == "```a`b`"

    def test_multiple_unmatched_backticks(self):
        assert render("`a``b`c") == "`a``b`c"

    def test_star_foo_star_star_bar_star(self):
        assert render("*foo**bar*") == "<em>foo**bar</em>"

    def test_triple_then_single_star(self):
        assert render("***a***") == "<em><strong>a</strong></em>"

    def test_double_then_single_star_unmatched(self):
        assert render("**a*") == "*<em>a</em>"

    def test_rule_of_3_sum_multiple_of_3_no_match(self):
        # Sum of lengths is multiple of 3: 1 + 2 = 3, so no match
        assert render("*a**") == "*a**"

    def test_code_span_contains_unmatched_backtick(self):
        assert render("`a`b`") == "<code>a</code>b`"

    def test_emphasis_between_code_spans(self):
        assert render("`a` *b* `c`") == "<code>a</code> <em>b</em> <code>c</code>"

    def test_complex_nested_structure(self):
        assert render("**a *b* `c`*d**") == "<strong>a <em>b</em> <code>c</code><em>d</em></strong>"


class TestPunctuation:
    """Test punctuation character handling in delimiter runs."""

    def test_punctuation_before_star_run(self):
        # punctuation before: *after* is not punctuation (letter)
        # So it's left-flanking
        assert render(".*hello*.") == ".<em>hello</em>."

    def test_punctuation_after_star_run_opposite_effect(self):
        assert render(".hello.") == ".hello."

    def test_space_before_and_after_star_no_emphasis(self):
        assert render("a * b * c") == "a * b * c"

    def test_star_at_start_with_non_whitespace_after_is_left_flanking(self):
        assert render("*hello*") == "<em>hello</em>"

    def test_star_at_end_with_non_whitespace_before_is_right_flanking(self):
        assert render("hello*") == "hello*"


class TestComplexCases:
    """Test complex real-world scenarios."""

    def test_markdown_with_all_features(self):
        assert render("**bold** *italic* `code` \\*escaped\\*") == "<strong>bold</strong> <em>italic</em> <code>code</code> *escaped*"

    def test_code_span_inside_emphasis(self):
        assert render("*use `code` here*") == "<em>use <code>code</code> here</em>"

    def test_multiple_emphasis_different_chars(self):
        assert render("*italic* and **bold**") == "<em>italic</em> and <strong>bold</strong>"

    def test_nested_different_emphasis_types(self):
        assert render("*_mixed_*") == "<em><em>mixed</em></em>"

    def test_star_vs_underscore_matching(self):
        assert render("_a* b*") == "_a* b*"

    def test_emphasized_code_span_with_special_chars(self):
        assert render("*`<tag>`*") == "<em><code>&lt;tag&gt;</code></em>"

    def test_multiple_backtick_strings_same_text(self):
        assert render("`` `code` ``") == "<code>`code`</code>"

    def test_emphasis_with_html_chars(self):
        assert render("*a&b*") == "<em>a&amp;b</em>"

    def test_very_long_delimiter_run(self):
        assert render("*" * 10 + "text" + "*" * 10) == "<em>" * 5 + "text" + "</em>" * 5

    def test_alternating_star_underscore(self):
        assert render("*a_b*") == "<em>a_b</em>"

    def test_code_at_boundaries(self):
        assert render("`start` middle `end`") == "<code>start</code> middle <code>end</code>"

    def test_escape_then_emphasis_char(self):
        # Escaped *, so it's not a delimiter run
        assert render("\\**text*") == "*<em>text</em>"

    def test_multiple_space_trimming_in_code_span(self):
        assert render("`  content  `") == "<code>content</code>"

import pytest
from mdinline import render


