class TestBackslashEscapes:
    """Test backslash escape handling."""

    def test_escaped_asterisk(self):
        assert render(r"\*") == "*"

    def test_escaped_asterisk_prevents_emphasis(self):
        assert render(r"\*not emphasis\*") == "*not emphasis*"

    def test_escaped_plus(self):
        assert render(r"\+") == "+"

    def test_escaped_bracket(self):
        assert render(r"\[") == "["

    def test_escaped_hash(self):
        assert render(r"\#") == "#"

    def test_escaped_underscore(self):
        assert render(r"\_") == "_"

    def test_escaped_backtick(self):
        assert render(r"\`") == "`"

    def test_backslash_before_non_ascii_punctuation_is_literal(self):
        # Backslash before non-ASCII character is literal
        assert render(r"\¡") == r"\¡"

    def test_backslash_before_letter_is_literal(self):
        assert render(r"\a") == r"\a"

    def test_backslash_before_digit_is_literal(self):
        assert render(r"\1") == r"\1"

    def test_backslash_at_end_of_line_is_literal(self):
        assert render("text\\") == "text\\"

    def test_backslash_inside_code_span_is_literal(self):
        assert render(r"`\*`") == "<code>\\*</code>"

    def test_multiple_escapes(self):
        assert render(r"\*\*\*") == "***"

    def test_escaped_asterisk_with_text(self):
        assert render(r"hello \* world") == "hello * world"


class TestCodeSpans:
    """Test code span handling."""

    def test_single_backtick_code_span(self):
        assert render("`a`") == "<code>a</code>"

    def test_code_span_with_asterisks(self):
        assert render("`a*b`") == "<code>a*b</code>"

    def test_code_span_with_underscores(self):
        assert render("`a_b`") == "<code>a_b</code>"

    def test_code_span_with_space_trimming_both_ends(self):
        assert render("` a `") == "<code>a</code>"

    def test_code_span_with_space_trimming_start_only(self):
        assert render("` a b`") == "<code>a b</code>"

    def test_code_span_with_space_trimming_end_only(self):
        assert render("`a b `") == "<code>a b</code>"

    def test_code_span_with_only_spaces_no_trimming(self):
        assert render("`   `") == "<code>   </code>"

    def test_code_span_with_space_and_newline_no_trimming(self):
        # Only spaces, so no trimming even though it starts and ends with space
        assert render("`     `") == "<code>     </code>"

    def test_double_backtick_code_span(self):
        assert render("``a``") == "<code>a</code>"

    def test_double_backtick_containing_single_backtick(self):
        assert render("``a ` b``") == "<code>a ` b</code>"

    def test_triple_backtick_code_span(self):
        assert render("```a```") == "<code>a</code>"

    def test_unmatched_backtick_is_literal(self):
        assert render("`a") == "`a"

    def test_backtick_with_wrong_length_closer_is_literal(self):
        assert render("`a``") == "`a``"

    def test_double_backtick_with_single_backtick_closer_continues_scan(self):
        assert render("``a`b`") == "``a`b`"

    def test_code_span_in_text(self):
        assert render("use `a*b` here") == "use <code>a*b</code> here"

    def test_code_spans_binds_tighter_than_emphasis(self):
        assert render("*a `*` b*") == "<em>a <code>*</code> b</em>"

