    def test_code_span_with_trailing_space_trimmed(self):
        assert render("`hello `") == "<code>hello</code>"

    def test_code_span_with_space_and_text_on_both_ends_trimmed(self):
        assert render("` hello world `") == "<code>hello world</code>"


class TestEmphasis:
    """Test emphasis (em) handling."""

    def test_single_asterisk_emphasis(self):
        assert render("*hello*") == "<em>hello</em>"

    def test_single_underscore_emphasis(self):
        assert render("_hello_") == "<em>hello</em>"

    def test_emphasis_with_text_before_after(self):
        assert render("hello *world* there") == "hello <em>world</em> there"

    def test_emphasis_with_special_characters(self):
        assert render("*a & b*") == "<em>a &amp; b</em>"

    def test_multiple_emphasis(self):
