    def test_emphasis_not_inside_word_with_underscore(self):
        assert render("snake_case_name") == "snake_case_name"

    def test_underscore_at_word_boundary_works(self):
        assert render("_hello_ world") == "<em>hello</em> world"

    def test_underscore_after_word_boundary_works(self):
        assert render("hello _world_") == "hello <em>world</em>"


class TestStrongEmphasis:
    """Test strong emphasis (strong) handling."""

    def test_double_asterisk_strong(self):
        assert render("**hello**") == "<strong>hello</strong>"

    def test_double_underscore_strong(self):
        assert render("__hello__") == "<strong>hello</strong>"

    def test_strong_with_text_before_after(self):
        assert render("hello **world** there") == "hello <strong>world</strong> there"

    def test_strong_with_special_characters(self):
        assert render("**a & b**") == "<strong>a &amp; b</strong>"

    def test_multiple_strong(self):
        assert render("**a** and **b**") == "<strong>a</strong> and <strong>b</strong>"


class TestMixedEmphasis:
    """Test combinations of emphasis and strong emphasis."""

    def test_emphasis_inside_strong(self):
        assert render("**bold *and* italic**") == "<strong>bold <em>and</em> italic</strong>"

    def test_strong_inside_emphasis(self):
        assert render("*italic **and** bold*") == "<em>italic <strong>and</strong> bold</em>"

    def test_triple_asterisk_start_as_em_strong(self):
        assert render("***hello***") == "<em><strong>hello</strong></em>"

    def test_triple_asterisk_other_order(self):
        assert render("***hello***") == "<em><strong>hello</strong></em>"

    def test_multiple_of_3_do_not_match(self):
        # Sum of lengths is 2 + 1 = 3 (multiple of 3)
        # Only matching if both lengths are multiples of 3
        assert render("*foo**bar*") == "<em>foo**bar</em>"

    def test_four_asterisks_matches_as_two_plus_two(self):
        assert render("**foo**") == "<strong>foo</strong>"

    def test_emphasis_then_strong(self):
        assert render("*Hello* **world**") == "<em>Hello</em> <strong>world</strong>"

    def test_nested_different_markers(self):
        assert render("*italic __bold italic__*") == "<em>italic <strong>bold italic</strong></em>"


class TestDelimiterRunRules:
    """Test delimiter run flanking and matching rules."""

    def test_delimiter_run_left_flanking(self):
        # * before 'a' (after is 'a', before is space)
        # left-flanking: after is not whitespace, after is not punctuation
        assert render("*a*") == "<em>a</em>"

    def test_delimiter_run_right_flanking(self):
        # * after 'a' (before is 'a', after is space)
        # right-flanking: before is not whitespace
        assert render("a *b* c") == "a <em>b</em> c"

    def test_asterisk_can_open_and_close(self):
        assert render("*hello*") == "<em>hello</em>"

    def test_underscore_does_not_open_inside_word(self):
        # between 'a' and 'b': left-flanking but not "before punctuation"
        assert render("a_b_c") == "a_b_c"

    def test_underscore_opens_at_start(self):
        assert render("_hello_ world") == "<em>hello</em> world"

    def test_underscore_closes_at_end_of_word(self):
        assert render("hello _world_") == "hello <em>world</em>"

    def test_underscore_with_punctuation_before_can_open(self):
        # Punctuation before underscore allows it to open
        assert render("._hello") == ".<em>hello</em>"

    def test_matching_left_to_right(self):
        # First closer matches nearest earlier opener
        assert render("*a* *b* *c*") == "<em>a</em> <em>b</em> <em>c</em>"

    def test_leftover_characters_in_delimiter_run(self):
        # **a* leaves one * that keeps matching
        assert render("**a*") == "*<em>a</em>"

    def test_triple_asterisk_consumes_as_strong_then_em(self):
        # ***a*** = take 2 from each for strong, then 1 from each for em
        assert render("***a***") == "<em><strong>a</strong></em>"


class TestEdgeCases:
    """Test edge cases and special scenarios."""

    def test_empty_string(self):
        assert render("") == ""

    def test_plain_text_no_markup(self):
        assert render("hello world") == "hello world"

    def test_single_character(self):
        assert render("a") == "a"

    def test_only_whitespace(self):
        assert render("   ") == "   "

    def test_code_span_binds_before_emphasis_inside(self):
        # The backtick inside prevents emphasis from being matched
        assert render("`*a*`") == "<code>*a*</code>"

    def test_matched_emphasis_delimiter_runs_cannot_rematch(self):
