    def test_mod_3_rule_sum_divisible_by_3_unequal_lengths(self):
        # Sum divisible by 3, lengths different and not both divisible by 3
        # *foo**bar* - opener 1, ** between, closer 1
        # Actually: position 0:*, position 4-5:**, position 9:*
        # Closer at 9 looks for opener: finds ** which can both open/close
        # Sum 2+1=3 divisible by 3, not both divisible → can't match
        # Then looks further: finds * at 0, sum 1+1=2 not divisible → can match
        assert render("*foo**bar*") == "<em>foo**bar</em>"

