        # For each closer, find nearest earlier opener that can match
        assert render("*a *b*") == "*a <em>b</em>"

    def test_unopened_closer_stays_as_text(self):
        # No matching opener
        assert render("text*") == "text*"

    def test_unmatched_opener_stays_as_text(self):
        # No matching closer
        assert render("*text") == "*text"

